from datetime import date, datetime


def filter_logs_by_date(logs: list[dict], target: str) -> list[dict]:
    """Filtrerar loggar vars 'ts' (ISO 8601) infaller på datumet `target` (YYYY-MM-DD)."""
    target_date = date.fromisoformat(target)

    def matchar(logg: dict) -> bool:
        ts = logg.get("ts")
        if not isinstance(ts, str):
            return False
        try:
            return datetime.fromisoformat(ts.replace("Z", "+00:00")).date() == target_date
        except ValueError:
            return False

    return [logg for logg in logs if matchar(logg)]


if __name__ == "__main__":
    loggar = [
        {"ts": "2027-02-11T08:00:00", "msg": "paradstart"},
        {"ts": "2027-02-12T09:30:00", "msg": "städning"},
    ]
    print(filter_logs_by_date(loggar, "2027-02-11"))
    # [{'ts': '2027-02-11T08:00:00', 'msg': 'paradstart'}]
