import ipaddress


def verify_access_log(log_path: str, allowed_ips: list[str]) -> list[str]:
    """
    Läser en åtkomstlogg (Common Log Format: IP först på raden) och returnerar
    unika IP-adresser som INTE finns i allowed_ips, i den ordning de först dyker upp.

    Stöder både enskilda IP-adresser och CIDR-nät i allowed_ips, t.ex. "10.0.0.0/8".
    """
    networks = []
    for entry in allowed_ips:
        try:
            networks.append(ipaddress.ip_network(entry.strip(), strict=False))
        except ValueError:
            continue  # Ignorera ogiltiga poster i allowlistan

    def is_allowed(ip: ipaddress._BaseAddress) -> bool:
        return any(ip in net for net in networks)

    disallowed: dict[str, None] = {}  # dict bevarar insättningsordning

    with open(log_path, "r", encoding="utf-8", errors="replace") as f:
        for line in f:
            token = line.split(maxsplit=1)[0] if line.strip() else ""
            if not token:
                continue
            try:
                ip = ipaddress.ip_address(token)
            except ValueError:
                continue  # Hoppa över rader som inte börjar med giltig IP
            if not is_allowed(ip):
                disallowed.setdefault(str(ip), None)

    return list(disallowed)
