import csv
from datetime import datetime


def parse_border_crossings(csv_path: str) -> list[dict]:
    """
    Parsar en CSV-fil med gränspassagedata (t.ex. Border Crossing Entry Data).

    Förväntade kolumner (skiftlägesokänsliga, mellanslag/_ ignoreras):
        port_name, state, port_code, border, date, measure, value,
        latitude, longitude

    Returnerar en lista av dictar med normaliserade nycklar och typer.
    Rader som saknar obligatoriska fält eller har ogiltiga värden hoppas över.
    """
    def norm(key: str) -> str:
        return key.strip().lower().replace(" ", "_").replace("-", "_")

    def to_float(value):
        try:
            return float(value)
        except (TypeError, ValueError):
            return None

    def to_date(value):
        for fmt in ("%Y-%m-%d", "%m/%d/%Y", "%b %Y", "%Y-%m", "%m/%d/%Y %I:%M:%S %p"):
            try:
                return datetime.strptime(value.strip(), fmt).date()
            except (AttributeError, ValueError):
                continue
        return None

    rows: list[dict] = []
    with open(csv_path, newline="", encoding="utf-8-sig") as f:
        reader = csv.DictReader(f)
        for raw in reader:
            row = {norm(k): (v.strip() if isinstance(v, str) else v)
                   for k, v in raw.items() if k}

            value = to_float(row.get("value"))
            if not row.get("port_name") or value is None:
                continue  # ogiltig rad

            rows.append({
                "port_name": row.get("port_name"),
                "state": row.get("state") or None,
                "port_code": row.get("port_code") or None,
                "border": row.get("border") or None,
                "date": to_date(row.get("date", "")),
                "measure": row.get("measure") or None,
                "value": int(value),
                "latitude": to_float(row.get("latitude")),
                "longitude": to_float(row.get("longitude")),
            })
    return rows
