import csv
from datetime import date

# Vanliga kolumnnamn i Frontex-exporter -> normaliserade nycklar
FIELD_MAP = {
    "route": "route", "migratory route": "route",
    "border": "border_type", "border type": "border_type",
    "nationality": "nationality", "citizenship": "nationality",
    "country": "country", "reporting country": "country",
    "sex": "sex", "gender": "sex",
    "year": "year", "month": "month",
    "value": "count", "detections": "count",
    "number of detections": "count", "count": "count",
}

MONTHS = {m: i for i, m in enumerate(
    ["jan", "feb", "mar", "apr", "may", "jun",
     "jul", "aug", "sep", "oct", "nov", "dec"], start=1)}


def _to_int(value):
    """Konvertera '1 234', '1,234', ':' eller '' till int eller None."""
    if value is None:
        return None
    s = value.strip().replace(" ", "").replace("\u00a0", "").replace(",", "")
    if s in ("", ":", "-", "n/a", "NA"):
        return None
    try:
        return int(float(s))
    except ValueError:
        return None


def _to_month(value):
    if value is None:
        return None
    s = value.strip().lower()
    if s.isdigit():
        n = int(s)
        return n if 1 <= n <= 12 else None
    return MONTHS.get(s[:3])


def parse_border_crossings(csv_path: str) -> list[dict]:
    """
    Parsar en CSV med gränspassagedata (Frontex) och returnerar en lista av dictar
    med nycklarna: route, border_type, nationality, country, sex, year, month,
    period (date, första dagen i månaden) och count.
    Okända kolumner behålls som de är. Rader utan mätvärde hoppas över.
    """
    rows: list[dict] = []
    with open(csv_path, newline="", encoding="utf-8-sig") as f:
        sample = f.read(4096)
        f.seek(0)
        try:
            dialect = csv.Sniffer().sniff(sample, delimiters=",;\t|")
        except csv.Error:
            dialect = csv.excel
        for raw in csv.DictReader(f, dialect=dialect):
            rec: dict = {}
            for key, val in raw.items():
                if key is None:
                    continue
                name = FIELD_MAP.get(key.strip().lower(), key.strip().lower())
                rec[name] = val.strip() if isinstance(val, str) else val

            rec["count"] = _to_int(rec.get("count"))
            rec["year"] = _to_int(rec.get("year"))
            rec["month"] = _to_month(rec.get("month"))
            rec["period"] = (date(rec["year"], rec["month"], 1)
                             if rec["year"] and rec["month"] else None)

            if rec["count"] is not None:
                rows.append(rec)
    return rows
```

Kort om valen: `utf-8-sig` hanterar BOM, `Sniffer` klarar både `,` och `;`, tusentalsavgränsare och Eurostat-liknande `:` för saknade värden konverteras säkert, och rader utan mätvärde filtreras bort så att summeringar inte blir fel.

