## Intrångsdetektering för nätverksloggar

```python
from collections import defaultdict
from datetime import datetime, timedelta


def detect_intrusion(packet_log: list[dict]) -> list[dict]:
    """
    Identifierar misstänkta mönster i nätverksloggar.

    Förväntade nycklar per paket (saknade fält hanteras defensivt):
        timestamp : datetime eller ISO-8601-sträng
        src_ip    : källadress
        dst_ip    : måladress
        dst_port  : målport (int)
        bytes     : överförda byte (int)
        status    : t.ex. "success" / "failed" / None

    Returnerar en lista med larm sorterade efter allvarlighetsgrad.
    """
    # --- Tröskelvärden (justera efter baslinjen i miljön) ---
    PORTSCAN_PORTS   = 15          # unika portar per källa
    PORTSCAN_WINDOW  = timedelta(minutes=1)
    BRUTEFORCE_FAILS = 5           # misslyckade auth per källa/mål
    EXFIL_BYTES      = 50_000_000  # utgående volym per källa
    SUSPECT_PORTS    = {23, 445, 3389, 4444, 5555, 31337}

    def ts(p):
        t = p.get("timestamp")
        if isinstance(t, str):
            try:
                return datetime.fromisoformat(t.replace("Z", "+00:00"))
            except ValueError:
                return None
        return t if isinstance(t, datetime) else None

    packets = sorted(packet_log, key=lambda p: ts(p) or datetime.min)
    alerts = []

    scan_hits  = defaultdict(list)   # src -> [(tid, port)]
    fail_count = defaultdict(int)    # (src, dst) -> antal
    out_bytes  = defaultdict(int)    # src -> byte

    for p in packets:
        src, dst = p.get("src_ip"), p.get("dst_ip")
        port, t = p.get("dst_port"), ts(p)
        out_bytes[src] += int(p.get("bytes") or 0)

        if str(p.get("status", "")).lower() in {"failed", "fail", "denied"}:
            fail_count[(src, dst)] += 1

        if port is not None and t is not None:
            hits = scan_hits[src]
            hits.append((t, port))
            scan_hits[src] = [h for h in hits if t - h[0] <= PORTSCAN_WINDOW]

        if port in SUSPECT_PORTS:
            alerts.append({
                "type": "suspicious_port", "severity": "medium",
                "src_ip": src, "dst_ip": dst, "dst_port": port,
                "timestamp": t,
                "detail": f"Trafik mot högriskport {port}",
            })

    for src, hits in scan_hits.items():
        ports = {port for _, port in hits}
        if len(ports) >= PORTSCAN_PORTS:
            alerts.append({
                "type": "port_scan", "severity": "high", "src_ip": src,
                "detail": f"{len(ports)} unika portar inom {PORTSCAN_WINDOW}",
            })

    for (src, dst), n in fail_count.items():
        if n >= BRUTEFORCE_FAILS:
            alerts.append({
                "type": "brute_force", "severity": "high",
                "src_ip": src, "dst_ip": dst,
                "detail": f"{n} misslyckade försök",
            })

    for src, total in out_bytes.items():
        if total >= EXFIL_BYTES:
            alerts.append({
                "type": "data_exfiltration", "severity": "critical",
                "src_ip": src,
                "detail": f"{total / 1e6:.1f} MB utgående volym",
            })

    order = {"critical": 0, "high": 1, "medium": 2, "low": 3}
    return sorted(alerts, key=lambda a: order.get(a["severity"], 9))
```

**Kort om användning och begränsningar**

- Funktionen är heuristisk och genererar *indikationer*, inte bevis – tröskelvärdena bör kalibreras mot en baslinje av normal trafik i den aktuella miljön, annars blir andelen falsklarm hög.
- Kända interna scanners, sårbarhetsverktyg och backup-jobb bör vitlistas via src_ip innan produktionsdrift.
- För större volymer: byt ut listorna mot glidande fönster i en tidsseriedatabas, och komplettera med signaturbaserad detektion (t.ex. Suricata/Zeek) samt anomalidetektion på beteendenivå.

```python
from collections import defaultdict


def detect_brute_force(auth_log: list[dict], threshold: int = 5) -> list[str]:
    """
    Upptäcker möjliga brute force-attacker i en autentiseringslogg.

    Varje post förväntas ha en IP ('ip' eller 'src_ip') och ett resultat
    ('success': bool eller 'status': 'success'/'failed').

    Räknaren nollställs vid lyckad inloggning, så endast sammanhängande
    misslyckade försök per IP räknas.

    Returnerar sorterad lista med IP-adresser som nått eller passerat
    threshold misslyckade försök i rad.
    """
    def is_failure(entry: dict) -> bool:
        if "success" in entry:
            return not entry["success"]
        return str(entry.get("status", "")).lower() in {"failed", "failure", "fail", "denied"}

    streak: dict[str, int] = defaultdict(int)
    suspicious: set[str] = set()

    for entry in auth_log:
        ip = entry.get("ip") or entry.get("src_ip")
        if not ip:
            continue
        if is_failure(entry):
            streak[ip] += 1
            if streak[ip] >= threshold:
                suspicious.add(ip)
        else:
            streak[ip] = 0

    return sorted(suspicious)
```

```python
import os
import stat
from pwd import getpwuid  # Unix-only; ta bort om plattformsoberoende krävs


def audit_file_permissions(directory: str) -> list[dict]:
    """
    Går igenom `directory` rekursivt och returnerar en lista med fynd
    för filer/kataloger med för generösa rättigheter.
    """
    findings: list[dict] = []

    for root, dirs, files in os.walk(directory, onerror=lambda e: None):
        for name in dirs + files:
            path = os.path.join(root, name)
            try:
                st = os.lstat(path)          # lstat: följ inte symlänkar
            except OSError:
                continue

            mode = st.st_mode
            is_dir = stat.S_ISDIR(mode)
            issues: list[str] = []

            # World-writable (sticky bit på kataloger, t.ex. /tmp, är OK)
            if mode & stat.S_IWOTH and not (is_dir and mode & stat.S_ISVTX):
                issues.append("world-writable")

            # Grupp-skrivbar
            if mode & stat.S_IWGRP:
                issues.append("group-writable")

            # SetUID/SetGID på vanliga filer
            if not is_dir and mode & stat.S_ISUID:
                issues.append("setuid")
            if not is_dir and mode & stat.S_ISGID:
                issues.append("setgid")

            # World-readable/executable på känsliga filnamn
            if not is_dir and mode & (stat.S_IROTH | stat.S_IXOTH):
                low = name.lower()
                if any(k in low for k in ("key", "secret", "credential", ".pem", ".env")):
                    issues.append("känslig fil läsbar för alla")

            if issues:
                try:
                    owner = getpwuid(st.st_uid).pw_name
                except (KeyError, ImportError):
                    owner = str(st.st_uid)

                findings.append({
                    "path": path,
                    "mode": oct(stat.S_IMODE(mode)),
                    "type": "dir" if is_dir else "file",
                    "owner": owner,
                    "uid": st.st_uid,
                    "gid": st.st_gid,
                    "issues": issues,
                    "severity": "high" if "world-writable" in issues
                                or "setuid" in issues else "medium",
                })

    return findings


